    "Use JsonReader.setStrictness(Strictness.LENIENT) to accept malformed JSON";

private JsonReader createStrictReader(String json) {
    JsonReader reader = new JsonReader(reader(json));
    reader.setStrictness(Strictness.STRICT);
    return reader;
}

@ParameterizedTest
@CsvSource({
    "'FALSE'",
    "'FaLse'"
})
public void testCapitalizedFalseFailWhenStrict(String input) {
    JsonReader reader = createStrictReader(input);
    IOException expected = assertThrows(
        "Reading boolean should fail for input \"" + input + "\" in strict mode",
        IOException.class,
        reader::nextBoolean);
    assertThat(expected)
        .hasMessageThat()
        .startsWith(EXPECTED_MESSAGE_PREFIX + " at line 1 column 1 path $\n");
}

