@Test
public void testMixedCaseLiterals_nullLiterals() throws IOException {
  JsonReader reader = createMixedCaseReader();
  // Skip the boolean literals
  reader.nextBoolean();
  reader.nextBoolean();
  reader.nextBoolean();
  reader.nextBoolean();

  assertWithMessage("Fifth literal 'NULL' should be a null token")
      .that(reader.peek())
      .isEqualTo(JsonToken.NULL);
  reader.nextNull();

  assertWithMessage("Sixth literal 'nulL' should be a null token")
      .that(reader.peek())
      .isEqualTo(JsonToken.NULL);
  reader.nextNull();
}

@Test
public void testMixedCaseLiterals_endDocument() throws IOException {
  JsonReader reader = createMixedCaseReader();

