  reader.nextBoolean(); // True
  reader.nextBoolean(); // TruE
  reader.nextBoolean(); // False
  reader.nextBoolean(); // FALSE
  reader.nextNull();    // NULL
  reader.nextNull();    // nulL
  reader.endArray();

  assertWithMessage("After consuming the array, the reader should be at END_DOCUMENT")
      .that(reader.peek())
