    String html = "<body><a href='./one.html'>One</a> <a href='two.html'>two</a> <a href='../three.html'>Three</a> <a href='//example2.com/four/'>Four</a> <a href='https://example2.com/five/'>Five</a>";
    Document doc = Jsoup.parse(html, "http://example.com/bar/");
    Elements els = doc.select("a");

    assertEquals("Relative URL './one.html' should resolve to http://example.com/bar/one.html",
            "http://example.com/bar/one.html", els.get(0).absUrl("href"));
    assertEquals("Relative URL 'two.html' should resolve to http://example.com/bar/two.html",
            "http://example.com/bar/two.html", els.get(1).absUrl("href"));
    assertEquals("Relative URL '../three.html' should resolve to http://example.com/three.html",
            "http://example.com/three.html", els.get(2).absUrl("href"));
    assertEquals("Protocol‑relative URL '//example2.com/four/' should resolve to http://example2.com/four/",
            "http://example2.com/four/", els.get(3).absUrl("href"));
    assertEquals("Absolute URL 'https://example2.com/five/' should remain unchanged",
            "https://example2.com/five/", els.get(4).absUrl("href"));
}

