private static final int EXPECTED_BR_TEXT_NODES = 0;
private static final String HTML_PARAGRAPH = "<p>One <span>Two</span> Three <br> Four</p>";

// Helper to create the document used by the tests
private Document createTestDocument() {
    return Jsoup.parse(HTML_PARAGRAPH);
}

/**
 * Verifies that the <p> element contains the expected number of text nodes
 * and that each text node has the correct content.
 */
@Test
public void testGetTextNodes_ParagraphContent() {
    Document doc = createTestDocument();
    Element paragraph = doc.select("p").first();
    List<TextNode> textNodes = paragraph.textNodes();

    assertEquals("Paragraph should contain exactly " + EXPECTED_PARAGRAPH_TEXT_NODES + " text nodes",
                 EXPECTED_PARAGRAPH_TEXT_NODES, textNodes.size());
    assertEquals("First text node should be 'One '", "One ", textNodes.get(0).text());
    assertEquals("Second text node should be ' Three '", " Three ", textNodes.get(1).text());
    assertEquals("Third text node should be ' Four'", " Four", textNodes.get(2).text());
}

/**
 * Verifies that the <br> element does not have any text nodes.
 */
@Test
public void testGetTextNodes_BrElementHasNoTextNodes() {
    Document doc = createTestDocument();
    Element br = doc.select("br").first();

    assertEquals("<br> element should have no text nodes",
                 EXPECTED_BR_TEXT_NODES, br.textNodes().size());
}

