@Test
public void testNewsHomepage(@TempDir File tempDir) throws IOException {
    // Locate the HTML fixture on the classpath
    URL resource = ParseTest.class.getResource("/htmltests/news-com-au-home.html");
    assertNotNull(resource, "Resource '/htmltests/news-com-au-home.html' must be present on the classpath");

    // Copy the fixture into the injected temporary directory
    Path targetPath = tempDir.toPath().resolve("news-com-au-home.html");
    Files.copy(Path.of(resource.toURI()), targetPath, StandardCopyOption.REPLACE_EXISTING);
    File in = targetPath.toFile();

    // Verify that the input file exists before parsing
    assertTrue(in.exists() && in.isFile(), "Input HTML file must exist before parsing");

    // Parse the document
    Document doc = Jsoup.parse(in, "UTF-8", "http://www.news.com.au/");

    // Assertions with descriptive messages
    assertEquals(
            "News.com.au | News from Australia and around the world online | NewsComAu",
            doc.title(),
            "Page title should match the expected value"
    );

    assertEquals(
            "Brace yourself for Metro meltdown",
            doc.select(".id1225817868581 h4").text().trim(),
            "Header text should match the expected headline"
    );

    Element a = doc.select("a[href=/entertainment/horoscopes]").first();
    assertEquals(
            "/entertainment/horoscopes",
            a.attr("href"),
            "Relative href attribute should be correct for the horoscopes link"
    );
    assertEquals(
            "http://www.news.com.au/entertainment/horoscopes",
            a.attr("abs:href"),
            "Absolute href attribute should resolve to the full URL for the horoscopes link"
    );

    Element hs = doc.select("a[href*=naughty-corners-are-a-bad-idea]").first();
    assertEquals(
            "http://www.heraldsun.com.au/news/naughty-corners-are-a-bad-idea-for-kids/story-e6frf7jo-1225817899003",
            hs.attr("href"),
            "Href attribute should contain the correct external URL for the naughty corners link"
    );
    assertEquals(
            hs.attr("href"),
            hs.attr("abs:href"),
            "Absolute href should be identical to the href attribute for external links"
    );
}

