@ParameterizedTest(name = "hasClass('{1}' in class attribute \"{0}\" ) => {2}")
@CsvSource({
    // true cases for class 'toto' (different whitespace variations)
    "'toto',               'toto',          true",
    "' toto',              'toto',          true",
    "'toto ',              'toto',          true",
    "'\\ttoto ',           'toto',          true",
    "'  toto ',            'toto',          true",
    // false cases for class 'toto'
    "'ab',                 'toto',          false",
    "'     ',               'toto',          false",
    "'tototo',             'toto',          false",
    // true cases for class 'raulpismuth' (different surrounding tokens)
    "'raulpismuth  ',      'raulpismuth',  true",
    "'abcd  raulpismuth efgh', 'raulpismuth', true",
    "'abcd efgh raulpismuth',   'raulpismuth', true",
    "'abcd efgh raulpismuth ',  'raulpismuth', true"
})
void testHasClassDomMethods(String classAttr, String queryClass, boolean expected) {
    Element el = createElementWithClass(classAttr);
    assertEquals(expected, el.hasClass(queryClass),
        String.format("Element.hasClass(\"%s\") should return %s when class attribute is \"%s\"",
                      queryClass, expected, classAttr));
}

