/**
 * Creates a {@link JsonReader} configured for lenient parsing and positioned at the start of an
 * object (i.e., after {@code beginObject()} has been called).
 *
 * @param json the JSON string to read
 * @return a {@code JsonReader} ready for further reading
 * @throws IOException if an I/O error occurs
 */
private JsonReader createLenientReader(String json) throws IOException {
    JsonReader reader = new JsonReader(reader(json));
    reader.setStrictness(Strictness.LENIENT);
    reader.beginObject();
    return reader;
}

