/* Helper methods */

private File copyResourceToTempDir(String resourcePath, File tempDir) throws IOException {
    URL resource = ParseTest.class.getResource(resourcePath);
    if (resource == null) {
        fail("Resource not found: " + resourcePath);
    }
    try (InputStream is = resource.openStream()) {
        Path target = tempDir.toPath().resolve(Path.of(resourcePath).getFileName());
        Files.copy(is, target, StandardCopyOption.REPLACE_EXISTING);
        return target.toFile();
    } catch (URISyntaxException e) {
        throw new IllegalStateException(e);
    }
}

private Document loadDocument(File tempDir) throws IOException {
    File in = copyResourceToTempDir("/htmltests/news-com-au-home.html", tempDir);
    assertTrue("Input HTML file must exist before parsing", in.exists());
    assertFalse("Input path should not be a directory", in.isDirectory());
    return Jsoup.parse(in, "UTF-8", "http://www.news.com.au/");
}

