private static final int EXPECTED_FORM_DATA_SIZE = 6;

private List<Connection.KeyVal> getFormData() {
    String html = "<form><input name='one' value='two'><select name='three'><option value='not'>"
            + "<option value='four' selected><option value='five' selected><textarea name=six>seven</textarea>"
            + "<input name='seven' type='radio' value='on' checked><input name='seven' type='radio' value='off'>"
            + "<input name='eight' type='checkbox' checked><input name='nine' type='checkbox' value='unset'>"
            + "<input name='ten' value='text' disabled>"
            + "<input name='eleven' value='text' type='button'>"
            + "</form>";
    Document doc = Jsoup.parse(html);
    FormElement form = (FormElement) doc.select("form").first();
    return form.formData();
}

@Test
public void createsFormData_verifyFormDataSize() {
    List<Connection.KeyVal> data = getFormData();
    assertEquals("Form should contain the expected number of submitted fields", EXPECTED_FORM_DATA_SIZE, data.size());
}

@Test
public void createsFormData_verifyFormFieldValues() {
    List<Connection.KeyVal> data = getFormData();

    String entry0 = data.get(0).toString();
    assertEquals("First entry should be the input field 'one' with value 'two'", "one=two", entry0);

    String entry1 = data.get(1).toString();
    assertEquals("Second entry should be the selected option 'four' for select 'three'", "three=four", entry1);

    String entry2 = data.get(2).toString();
    assertEquals("Third entry should be the selected option 'five' for select 'three'", "three=five", entry2);

    String entry3 = data.get(3).toString();
    assertEquals("Fourth entry should be the textarea 'six' with content 'seven'", "six=seven", entry3);

    String entry4 = data.get(4).toString();
    assertEquals("Fifth entry should be the checked radio button 'seven' with value 'on'", "seven=on", entry4);

    String entry5 = data.get(5).toString();
    assertEquals("Sixth entry should be the checked checkbox 'eight' with default value 'on'", "eight=on", entry5);
}

@Test
public void createsFormData_verifyExclusions() {
    List<Connection.KeyVal> data = getFormData();

    boolean containsNine = data.stream().anyMatch(kv -> kv.key().equals("nine"));
    boolean containsTen = data.stream().anyMatch(kv -> kv.key().equals("ten"));
    boolean containsEleven = data.stream().anyMatch(kv -> kv.key().equals("eleven"));

    assertEquals("Unchecked checkbox 'nine' should not be submitted", false, containsNine);
    assertEquals("Disabled input 'ten' should not be submitted", false, containsTen);
    assertEquals("Button input 'eleven' should not be submitted", false, containsEleven);
}

